#!/usr/bin/env bash
# Attaches Assets/StoreKit/VirtualPercussionist.storekit to the Run action of the
# generated Xcode scheme, so a Run from Xcode (iPhone, iPad or simulator) buys
# with fake money and a fast clock. The scheme is generated by CMake and is
# rewritten by every configure, so run this after ./scripts/configure-ios.sh.
# Debug > StoreKit > Manage Transactions then shows the fake purchases.
# The identifier below is exactly what Xcode itself writes when the file is
# picked in Edit Scheme > Run > Options (checked 2026-10-16). The file is also in
# the generated project (CMakeLists.txt) - without that, the picker says None.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SCHEME="$ROOT/build-ios/VirtualPercussionist.xcodeproj/xcshareddata/xcschemes/VirtualPercussionist.xcscheme"
[[ -f "$SCHEME" ]] || { echo "no scheme: run ./scripts/configure-ios.sh first"; exit 1; }
python3 - "$SCHEME" <<'PY'
import sys
p = sys.argv[1]
s = open(p).read()
ref = '      <StoreKitConfigurationFileReference\n         identifier = "../../../Assets/StoreKit/VirtualPercussionist.storekit">\n      </StoreKitConfigurationFileReference>\n'
if 'StoreKitConfigurationFileReference' in s:
    print("already attached")
else:
    a = s.index('<LaunchAction')
    b = s.index('</LaunchAction>', a)
    s = s[:b] + ref + '   ' + s[b:]
    open(p, 'w').write(s)
    print("attached")
PY
